#!/bin/bash
# Generated by betabench structure. Sorts source videos into the
# folders betaconfig.profile_by_source_dir maps to profiles.
#
# READ THE REASONS BELOW FIRST. The compilation/scene boundary is a
# heuristic read off a small sample, and split-screen is detected
# from box geometry, not from anything infallible.
#
# Every move is `mv -n`: it will not overwrite an existing file.
# Safe to re-run; already-moved files are skipped.
#
# usage: moves.sh [--include-held-back]
#   Moves the first section. The HELD BACK section, if there is one,
#   is only reported until you pass --include-held-back: those moves
#   rest on judgments the measurement cannot see (a folder you chose,
#   a lower sample rate, a slice instead of the whole file).

set -uo pipefail
moved=0; skipped=0; held=0; include_held_back=0

for arg in "$@"; do
    case "$arg" in
        --include-held-back|-a) include_held_back=1 ;;
        -h|--help) echo "usage: $0 [--include-held-back]"; exit 0 ;;
        *) echo "unknown argument: $arg" >&2; echo "usage: $0 [--include-held-back]" >&2; exit 2 ;;
    esac
done

move_one() {
    local src="$1" dest_dir="$2"
    if [[ ! -f "$src" ]]; then
        echo "skip (not found): $src"; skipped=$((skipped+1)); return
    fi
    if [[ -e "$dest_dir/${src##*/}" ]]; then
        echo "skip (target exists): $src"; skipped=$((skipped+1)); return
    fi
    mkdir -p "$dest_dir" || return
    if mv -n "$src" "$dest_dir"/; then
        if [[ -f "$src" ]]; then
            echo "skip (target exists): $src"; skipped=$((skipped+1))
        else
            echo "moved: $src -> $dest_dir/"; moved=$((moved+1))
        fi
    else
        echo "FAILED: $src"; skipped=$((skipped+1))
    fi
}

move_held() {
    local src="$1" dest_dir="$2" reason="$3"
    if [[ "$include_held_back" -eq 1 ]]; then
        move_one "$src" "$dest_dir"
    elif [[ -f "$src" ]]; then
        echo "held back: $src ($reason)"; held=$((held+1))
    fi
}

